function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

const products = [];
let globalIndex = 1;

for (const cat of CATEGORIES) {
  cat.items.forEach((item, idx) => {
    const padIdx = String(idx + 1).padStart(3, '0');
    const id = `prod-${cat.prefix}-${padIdx}`;
    const slug = slugify(item.name);
    const sku = `${cat.skuPrefix}-${item.brand.replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase()}-${padIdx}`;
    
    // Vary stock: product #50 in each category is set to 0 stock to test out-of-stock badge and alternatives!
    const stockQuantity = (idx === 49) ? 0 : (idx % 7 === 0 ? 3 : 15 + ((idx * 7) % 65));
    const discount = item.compareAt > item.price ? Math.round(((item.compareAt - item.price) / item.compareAt) * 100) : 0;
    const rating = Number((4.2 + ((idx * 3) % 8) / 10).toFixed(1));
    const reviewCount = 18 + ((idx * 17) % 450);

    const imgBase = `https://images.unsplash.com/${item.img}?auto=format&fit=crop`;
    const thumbnail = `${imgBase}&w=800&q=80`;
    const img1 = `${imgBase}&w=1000&q=80`;
    const img2 = `https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1000&q=80`;

    const product = {
      id,
      slug,
      title: item.name,
      brand: item.brand,
      category: cat.category,
      categorySlug: cat.categorySlug,
      description: `Experience the pinnacle of design, craftsmanship, and performance with the ${item.name}. Engineered by ${item.brand} for discerning customers who demand uncompromising quality, reliability, and precision. Tested and backed by authentic manufacturer warranty and ShopSphere guarantee.`,
      shortDescription: `Official ${item.brand} ${item.name} with premium build and guaranteed authenticity.`,
      price: item.price,
      compareAtPrice: item.compareAt,
      discountPercent: discount,
      rating,
      reviewCount,
      stockQuantity,
      isAvailable: stockQuantity > 0,
      isFeatured: idx < 6,
      isBestSeller: idx >= 6 && idx < 12,
      isDealOfTheDay: idx === 0,
      dealEndsAt: idx === 0 ? '2026-10-31T23:59:59Z' : undefined,
      sku,
      thumbnail,
      images: [img1, img2],
      tags: [cat.categorySlug, item.brand.toLowerCase(), item.tag, 'authentic', 'official'],
      features: [
        `Genuine authentic ${item.brand} craftsmanship`,
        `100% verified original merchandise with full warranty`,
        `Express doorstep dispatch and hassle-free returns`,
      ],
      specifications: [
        {
          group: 'Product Details',
          attributes: [
            { name: 'Brand', value: item.brand },
            { name: 'Model / Edition', value: item.name.split(' ').slice(0, 4).join(' ') },
            { name: 'Category', value: cat.category },
            { name: 'SKU', value: sku },
          ]
        },
        {
          group: 'Warranty & Support',
          attributes: [
            { name: 'Manufacturer Warranty', value: '1 Year Brand Warranty' },
            { name: 'Country of Origin', value: 'Global' },
            { name: 'Return Policy', value: '7-Day Return / Replacement' },
          ]
        }
      ],
      createdAt: new Date(1760000000000 - globalIndex * 3600000 * 4).toISOString(),
    };

    products.push(product);
    globalIndex++;
  });
}

console.log(`Generated ${products.length} products across ${CATEGORIES.length} categories.`);
CATEGORIES.forEach(c => {
  const count = products.filter(p => p.categorySlug === c.categorySlug).length;
  console.log(`- ${c.category} (${c.categorySlug}): ${count} items`);
});

